package behavioral.chainofresponsibility.sample;

public interface ISupportHandler {
    void setNext(ISupportHandler next);
    void handle(String issue, int difficultyLevel);
}

package behavioral.chainofresponsibility.sample;

import behavioral.chainofresponsibility.sample.supporthandlers.JuniorEngineer;
import behavioral.chainofresponsibility.sample.supporthandlers.L1SupportEngineer;
import behavioral.chainofresponsibility.sample.supporthandlers.L2SupportEngineer;
import behavioral.chainofresponsibility.sample.supporthandlers.SeniorEngineer;

public class Main {
    public static void main(String[] args) {

        ISupportHandler l1 = new L1SupportEngineer();
        ISupportHandler l2 = new L2SupportEngineer();
        ISupportHandler junior = new JuniorEngineer();
        ISupportHandler senior = new SeniorEngineer();

        l1.setNext(l2);
        l2.setNext(junior);
        junior.setNext(senior);

        l1.handle("PNF", 2);

        l1.handle("ABC", 10);
    }
}

package behavioral.chainofresponsibility.sample.supporthandlers;

import behavioral.chainofresponsibility.sample.ISupportHandler;

public class JuniorEngineer implements ISupportHandler {
    private ISupportHandler next;
    private final int THRESHOLD = 3;

    @Override
    public void setNext(ISupportHandler next){
        this.next = next;
    }

    @Override
    public void handle(String issue, int difficultyLevel){
        if (difficultyLevel <= this.THRESHOLD) {
            System.out.println("L1 Support handled the issue " + issue  + " of difficulty level : " + difficultyLevel + "\n");
        } else if (this.next != null) {
            System.out.println("Passing the issue from junior engineer to next level");
            this.next.handle(issue, difficultyLevel);
        }
    }
}

